// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 <= 1000 ether && amount2 <= 1000 ether);

        address actor = address(0xABCD);
        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount1 + amount2);
    }
}
